		//}
		// else
		//{
		//	js->_touchScrollX.reset(js->_timeNow);
		//	js->_touchScrollY.reset(js->_timeNow);
		//}
		//}
		// else
		//{
		//	js->_touchScrollX.reset(js->_timeNow);
		//	js->_touchScrollY.reset(js->_timeNow);
		//  if (point0.isDown() ^ point1.isDown()) // XOR
